/**
 * Rounds a cent amount half away from zero.
 *
 * @param {number} cents The unrounded amount.
 * @returns {number} Whole cents.
 */
export function roundCents(cents) {
  return Math.sign(cents) * Math.round(Math.abs(cents));
}
