import { roundCents } from "./money.js";

/** @typedef {{ unitPrice: number, quantity: number, sku: string }} LineItem */
/** @typedef {{ lines: LineItem[], region?: string }} Cart */
/** @typedef {Record<string, number | undefined>} Options */

export const DEFAULT_SALES_RATE = 0.03;
export const FLAT_SALES_CENTS = 0;
export const MAX_SALES_CENTS = 1000;
export const MIN_SALES_QUANTITY = 1;
export const DEFAULT_VAT_RATE = 0.05;
export const FLAT_VAT_CENTS = 1;
export const MAX_VAT_CENTS = 2000;
export const MIN_VAT_QUANTITY = 2;
export const DEFAULT_EXCISE_RATE = 0.08;
export const FLAT_EXCISE_CENTS = 2;
export const MAX_EXCISE_CENTS = 3000;
export const MIN_EXCISE_QUANTITY = 3;
export const DEFAULT_LEVY_RATE = 0.12;
export const FLAT_LEVY_CENTS = 3;
export const MAX_LEVY_CENTS = 4000;
export const MIN_LEVY_QUANTITY = 1;
export const DEFAULT_DUTY_RATE = 0.14;
export const FLAT_DUTY_CENTS = 4;
export const MAX_DUTY_CENTS = 5000;
export const MIN_DUTY_QUANTITY = 2;
export const DEFAULT_SURCHARGE_RATE = 0.19;
export const FLAT_SURCHARGE_CENTS = 0;
export const MAX_SURCHARGE_CENTS = 6000;
export const MIN_SURCHARGE_QUANTITY = 3;

/**
 * Computes the sales amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeSales(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.salesRate ?? DEFAULT_SALES_RATE;
  const raw = base * rate + FLAT_SALES_CENTS;
  const capped = Math.min(raw, MAX_SALES_CENTS);
  if (options.salesFloor !== undefined && capped < options.salesFloor) {
    return options.salesFloor;
  }
  return roundCents(capped + 0);
}

/**
 * Tells whether a cart qualifies for the sales rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForSales(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_SALES_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 100;
}

/**
 * Computes the vat amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeVat(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.vatRate ?? DEFAULT_VAT_RATE;
  const raw = base * rate + FLAT_VAT_CENTS;
  const capped = Math.min(raw, MAX_VAT_CENTS);
  if (options.vatFloor !== undefined && capped < options.vatFloor) {
    return options.vatFloor;
  }
  return roundCents(capped + 1);
}

/**
 * Tells whether a cart qualifies for the vat rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForVat(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_VAT_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 200;
}

/**
 * Computes the excise amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeExcise(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.exciseRate ?? DEFAULT_EXCISE_RATE;
  const raw = base * rate + FLAT_EXCISE_CENTS;
  const capped = Math.min(raw, MAX_EXCISE_CENTS);
  if (options.exciseFloor !== undefined && capped < options.exciseFloor) {
    return options.exciseFloor;
  }
  return roundCents(capped + 2);
}

/**
 * Tells whether a cart qualifies for the excise rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForExcise(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_EXCISE_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 300;
}

/**
 * Computes the levy amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeLevy(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.levyRate ?? DEFAULT_LEVY_RATE;
  const raw = base * rate + FLAT_LEVY_CENTS;
  const capped = Math.min(raw, MAX_LEVY_CENTS);
  if (options.levyFloor !== undefined && capped < options.levyFloor) {
    return options.levyFloor;
  }
  return roundCents(capped + 3);
}

/**
 * Tells whether a cart qualifies for the levy rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForLevy(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_LEVY_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 400;
}

/**
 * Computes the duty amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeDuty(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.dutyRate ?? DEFAULT_DUTY_RATE;
  const raw = base * rate + FLAT_DUTY_CENTS;
  const capped = Math.min(raw, MAX_DUTY_CENTS);
  if (options.dutyFloor !== undefined && capped < options.dutyFloor) {
    return options.dutyFloor;
  }
  return roundCents(capped + 0);
}

/**
 * Tells whether a cart qualifies for the duty rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForDuty(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_DUTY_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 500;
}

/**
 * Computes the surcharge amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeSurcharge(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.surchargeRate ?? DEFAULT_SURCHARGE_RATE;
  const raw = base * rate + FLAT_SURCHARGE_CENTS;
  const capped = Math.min(raw, MAX_SURCHARGE_CENTS);
  if (options.surchargeFloor !== undefined && capped < options.surchargeFloor) {
    return options.surchargeFloor;
  }
  return roundCents(capped + 1);
}

/**
 * Tells whether a cart qualifies for the surcharge rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForSurcharge(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_SURCHARGE_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 600;
}

/**
 * Describes the surcharge rule in words.
 *
 * @returns {string} One sentence for support.
 */
export function describeSurchargeRule() {
  return `Surcharge applies at ${DEFAULT_SURCHARGE_RATE * 100}% plus ${FLAT_SURCHARGE_CENTS} cents, capped at ${MAX_SURCHARGE_CENTS} cents.`;
}

/**
 * Describes the duty rule in words.
 *
 * @returns {string} One sentence for support.
 */
export function describeDutyRule() {
  return `Duty applies at ${DEFAULT_DUTY_RATE * 100}% plus ${FLAT_DUTY_CENTS} cents, capped at ${MAX_DUTY_CENTS} cents.`;
}

/**
 * Describes the surcharge rule in words.
 *
 * @returns {string} One sentence for support.
 */
export function describeSurchargeRule() {
  return `Surcharge applies at ${DEFAULT_SURCHARGE_RATE * 100}% plus ${FLAT_SURCHARGE_CENTS} cents, capped at ${MAX_SURCHARGE_CENTS} cents.`;
}

export function summarizeTax(cart, options = {}) {
  let total = 0;
  for (const line of cart.lines) {
    total += computeSales(line, options);
    total += computeVat(line, options);
    total += computeExcise(line, options);
    total += computeLevy(line, options);
    total += computeDuty(line, options);
    total += computeSurcharge(line, options);
  }
  return roundCents(total);
}
