import { describe, expect, test } from "bun:test";
import * as pricing from "../src/tax.js";

describe("tax", () => {
  test("sales is zero for an empty line", () => {
    expect(pricing.computeSales({ sku: "A0", unitPrice: 0, quantity: 3 })).toBe(0);
  });

  test("sales grows with the quantity", () => {
    const one = pricing.computeSales({ sku: "A0", unitPrice: 1000, quantity: 1 });
    const two = pricing.computeSales({ sku: "A0", unitPrice: 1000, quantity: 2 });
    expect(two).toBeGreaterThanOrEqual(one);
  });

  test("vat is zero for an empty line", () => {
    expect(pricing.computeVat({ sku: "A1", unitPrice: 0, quantity: 3 })).toBe(0);
  });

  test("vat grows with the quantity", () => {
    const one = pricing.computeVat({ sku: "A1", unitPrice: 1000, quantity: 1 });
    const two = pricing.computeVat({ sku: "A1", unitPrice: 1000, quantity: 2 });
    expect(two).toBeGreaterThanOrEqual(one);
  });

  test("excise is zero for an empty line", () => {
    expect(pricing.computeExcise({ sku: "A2", unitPrice: 0, quantity: 3 })).toBe(0);
  });

  test("excise grows with the quantity", () => {
    const one = pricing.computeExcise({ sku: "A2", unitPrice: 1000, quantity: 1 });
    const two = pricing.computeExcise({ sku: "A2", unitPrice: 1000, quantity: 2 });
    expect(two).toBeGreaterThanOrEqual(one);
  });

  test("levy is zero for an empty line", () => {
    expect(pricing.computeLevy({ sku: "A3", unitPrice: 0, quantity: 3 })).toBe(0);
  });

  test("levy grows with the quantity", () => {
    const one = pricing.computeLevy({ sku: "A3", unitPrice: 1000, quantity: 1 });
    const two = pricing.computeLevy({ sku: "A3", unitPrice: 1000, quantity: 2 });
    expect(two).toBeGreaterThanOrEqual(one);
  });

  test("duty is zero for an empty line", () => {
    expect(pricing.computeDuty({ sku: "A4", unitPrice: 0, quantity: 3 })).toBe(0);
  });

  test("duty grows with the quantity", () => {
    const one = pricing.computeDuty({ sku: "A4", unitPrice: 1000, quantity: 1 });
    const two = pricing.computeDuty({ sku: "A4", unitPrice: 1000, quantity: 2 });
    expect(two).toBeGreaterThanOrEqual(one);
  });

  test("surcharge is zero for an empty line", () => {
    expect(pricing.computeSurcharge({ sku: "A5", unitPrice: 0, quantity: 3 })).toBe(0);
  });

  test("surcharge grows with the quantity", () => {
    const one = pricing.computeSurcharge({ sku: "A5", unitPrice: 1000, quantity: 1 });
    const two = pricing.computeSurcharge({ sku: "A5", unitPrice: 1000, quantity: 2 });
    expect(two).toBeGreaterThanOrEqual(one);
  });

  test("added case 1", () => {
    expect(typeof pricing.describeSurchargeRule()).toBe("string");
  });

  test("added case 2", () => {
    expect(typeof pricing.describeDutyRule()).toBe("string");
  });

  test("added case 3", () => {
    expect(typeof pricing.describeSurchargeRule()).toBe("string");
  });
});
