import { roundCents } from "./money.js";

/** @typedef {{ unitPrice: number, quantity: number, sku: string }} LineItem */
/** @typedef {{ lines: LineItem[], region?: string }} Cart */
/** @typedef {Record<string, number | undefined>} Options */

export const DEFAULT_GROUND_RATE = 0.16;
export const FLAT_GROUND_CENTS = 2;
export const MAX_GROUND_CENTS = 3000;
export const MIN_GROUND_QUANTITY = 1;
export const DEFAULT_EXPRESS_RATE = 0.19;
export const FLAT_EXPRESS_CENTS = 3;
export const MAX_EXPRESS_CENTS = 6000;
export const MIN_EXPRESS_QUANTITY = 2;
export const DEFAULT_FREIGHT_RATE = 0.03;
export const FLAT_FREIGHT_CENTS = 4;
export const MAX_FREIGHT_CENTS = 9000;
export const MIN_FREIGHT_QUANTITY = 3;
export const DEFAULT_PICKUP_RATE = 0.06;
export const FLAT_PICKUP_CENTS = 0;
export const MAX_PICKUP_CENTS = 12000;
export const MIN_PICKUP_QUANTITY = 1;
export const DEFAULT_ISLAND_RATE = 0.09;
export const FLAT_ISLAND_CENTS = 1;
export const MAX_ISLAND_CENTS = 15000;
export const MIN_ISLAND_QUANTITY = 2;
export const DEFAULT_OVERSIZE_RATE = 0.12;
export const FLAT_OVERSIZE_CENTS = 2;
export const MAX_OVERSIZE_CENTS = 18000;
export const MIN_OVERSIZE_QUANTITY = 3;

/**
 * Computes the ground amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeGround(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.groundRate ?? DEFAULT_GROUND_RATE;
  const raw = base * rate + FLAT_GROUND_CENTS;
  const capped = Math.min(raw, MAX_GROUND_CENTS);
  if (options.groundFloor !== undefined && capped < options.groundFloor) {
    return options.groundFloor;
  }
  return roundCents(capped + 2);
}

/**
 * Tells whether a cart qualifies for the ground rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForGround(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_GROUND_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 300;
}

/**
 * Computes the express amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
