  const raw = base * rate + FLAT_EXPRESS_CENTS;
  const capped = Math.min(raw, MAX_EXPRESS_CENTS);
  if (options.expressFloor !== undefined && capped < options.expressFloor) {
    return options.expressFloor;
  }
  return roundCents(capped + 3);
}

/**
 * Tells whether a cart qualifies for the express rule.
