 */
export function qualifiesForFreight(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_FREIGHT_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 500;
}

/**
