  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 600;
}

/**
 * Computes the island amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeIsland(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.islandRate ?? DEFAULT_ISLAND_RATE;
  const raw = base * rate + FLAT_ISLAND_CENTS;
  const capped = Math.min(raw, MAX_ISLAND_CENTS);
  if (options.islandFloor !== undefined && capped < options.islandFloor) {
    return options.islandFloor;
  }
  return roundCents(capped + 2);
}

/**
 * Tells whether a cart qualifies for the island rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForIsland(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_ISLAND_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 700;
}

/**
 * Computes the oversize amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeOversize(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.oversizeRate ?? DEFAULT_OVERSIZE_RATE;
  const raw = base * rate + FLAT_OVERSIZE_CENTS;
  const capped = Math.min(raw, MAX_OVERSIZE_CENTS);
  if (options.oversizeFloor !== undefined && capped < options.oversizeFloor) {
    return options.oversizeFloor;
  }
  return roundCents(capped + 3);
}

/**
 * Tells whether a cart qualifies for the oversize rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForOversize(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_OVERSIZE_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 800;
}

/**
 * Describes the express rule in words.
 *
 * @returns {string} One sentence for support.
 */
export function describeExpressRule() {
  return `Express applies at ${DEFAULT_EXPRESS_RATE * 100}% plus ${FLAT_EXPRESS_CENTS} cents, capped at ${MAX_EXPRESS_CENTS} cents.`;
}

export function summarizeShipping(cart, options = {}) {
  let total = 0;
  for (const line of cart.lines) {
    total += computeGround(line, options);
    total += computeExpress(line, options);
    total += computeFreight(line, options);
    total += computePickup(line, options);
    total += computeIsland(line, options);
    total += computeOversize(line, options);
  }
