/** @typedef {{ unitPrice: number, quantity: number, sku: string }} LineItem */
/** @typedef {{ lines: LineItem[], region?: string }} Cart */
/** @typedef {Record<string, number | undefined>} Options */

export const DEFAULT_HEADER_RATE = 0.07;
export const FLAT_HEADER_CENTS = 1;
export const MAX_HEADER_CENTS = 7000;
export const MIN_HEADER_QUANTITY = 1;
export const DEFAULT_FOOTER_RATE = 0.09;
export const FLAT_FOOTER_CENTS = 2;
export const MAX_FOOTER_CENTS = 14000;
export const MIN_FOOTER_QUANTITY = 2;
export const DEFAULT_ITEMLINE_RATE = 0.12;
export const FLAT_ITEMLINE_CENTS = 3;
export const MAX_ITEMLINE_CENTS = 21000;
export const MIN_ITEMLINE_QUANTITY = 3;
export const DEFAULT_SUMMARY_RATE = 0.15;
export const FLAT_SUMMARY_CENTS = 4;
export const MAX_SUMMARY_CENTS = 28000;
export const MIN_SUMMARY_QUANTITY = 1;
export const DEFAULT_BARCODE_RATE = 0.18;
export const FLAT_BARCODE_CENTS = 0;
export const MAX_BARCODE_CENTS = 35000;
export const MIN_BARCODE_QUANTITY = 2;
export const DEFAULT_LOCALE_RATE = 0.02;
export const FLAT_LOCALE_CENTS = 1;
export const MAX_LOCALE_CENTS = 42000;
export const MIN_LOCALE_QUANTITY = 3;

/**
 * Computes the header amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeHeader(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.headerRate ?? DEFAULT_HEADER_RATE;
  const raw = base * rate + FLAT_HEADER_CENTS;
  const capped = Math.min(raw, MAX_HEADER_CENTS);
  if (options.headerFloor !== undefined && capped < options.headerFloor) {
    return options.headerFloor;
  }
  return roundCents(capped + 2);
}

/**
 * Tells whether a cart qualifies for the header rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForHeader(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_HEADER_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 700;
}

/**
 * Computes the footer amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
