  }
  return roundCents(capped + 1);
}

/**
 * Tells whether a cart qualifies for the summary rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForSummary(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_SUMMARY_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 1000;
}

/**
 * Computes the barcode amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
