  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 1100;
}

/**
 * Computes the locale amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeLocale(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
