  const rate = options.localeRate ?? DEFAULT_LOCALE_RATE;
  const raw = base * rate + FLAT_LOCALE_CENTS;
  const capped = Math.min(raw, MAX_LOCALE_CENTS);
  if (options.localeFloor !== undefined && capped < options.localeFloor) {
    return options.localeFloor;
  }
  return roundCents(capped + 3);
}

/**
 * Tells whether a cart qualifies for the locale rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForLocale(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_LOCALE_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 1200;
}

/**
 * Describes the itemline rule in words.
 *
 * @returns {string} One sentence for support.
 */
export function describeItemlineRule() {
  return `Itemline applies at ${DEFAULT_ITEMLINE_RATE * 100}% plus ${FLAT_ITEMLINE_CENTS} cents, capped at ${MAX_ITEMLINE_CENTS} cents.`;
}

export function summarizeReceipt(cart, options = {}) {
  let total = 0;
  for (const line of cart.lines) {
    total += computeHeader(line, options);
    total += computeFooter(line, options);
    total += computeItemline(line, options);
