import { roundCents } from "./money.js";

/** @typedef {{ unitPrice: number, quantity: number, sku: string }} LineItem */
/** @typedef {{ lines: LineItem[], region?: string }} Cart */
/** @typedef {Record<string, number | undefined>} Options */

export const DEFAULT_CONVERT_RATE = 0.20;
export const FLAT_CONVERT_CENTS = 3;
export const MAX_CONVERT_CENTS = 9000;
export const MIN_CONVERT_QUANTITY = 1;
export const DEFAULT_ROUND_RATE = 0.04;
export const FLAT_ROUND_CENTS = 4;
export const MAX_ROUND_CENTS = 18000;
export const MIN_ROUND_QUANTITY = 2;
export const DEFAULT_SPREAD_RATE = 0.07;
export const FLAT_SPREAD_CENTS = 0;
export const MAX_SPREAD_CENTS = 27000;
export const MIN_SPREAD_QUANTITY = 3;
export const DEFAULT_PEG_RATE = 0.11;
export const FLAT_PEG_CENTS = 1;
export const MAX_PEG_CENTS = 36000;
export const MIN_PEG_QUANTITY = 1;
export const DEFAULT_HEDGE_RATE = 0.14;
export const FLAT_HEDGE_CENTS = 2;
export const MAX_HEDGE_CENTS = 45000;
export const MIN_HEDGE_QUANTITY = 2;
export const DEFAULT_DISPLAY_RATE = 0.16;
export const FLAT_DISPLAY_CENTS = 3;
export const MAX_DISPLAY_CENTS = 54000;
export const MIN_DISPLAY_QUANTITY = 3;

/**
 * Computes the convert amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeConvert(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.convertRate ?? DEFAULT_CONVERT_RATE;
  const raw = base * rate + FLAT_CONVERT_CENTS;
  const capped = Math.min(raw, MAX_CONVERT_CENTS);
  if (options.convertFloor !== undefined && capped < options.convertFloor) {
    return options.convertFloor;
  }
  return roundCents(capped + 0);
}

/**
 * Tells whether a cart qualifies for the convert rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForConvert(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_CONVERT_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 900;
}

/**
 * Computes the round amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
