  const raw = base * rate + FLAT_ROUND_CENTS;
  const capped = Math.min(raw, MAX_ROUND_CENTS);
  if (options.roundFloor !== undefined && capped < options.roundFloor) {
    return options.roundFloor;
  }
  return roundCents(capped + 1);
}

