  }
  return roundCents(capped + 3);
}

/**
 * Tells whether a cart qualifies for the peg rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForPeg(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_PEG_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 1200;
}

/**
 * Computes the hedge amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeHedge(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.hedgeRate ?? DEFAULT_HEDGE_RATE;
  const raw = base * rate + FLAT_HEDGE_CENTS;
  const capped = Math.min(raw, MAX_HEDGE_CENTS);
  if (options.hedgeFloor !== undefined && capped < options.hedgeFloor) {
    return options.hedgeFloor;
  }
  return roundCents(capped + 0);
}

/**
 * Tells whether a cart qualifies for the hedge rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForHedge(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_HEDGE_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 1300;
}

/**
 * Computes the display amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeDisplay(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.displayRate ?? DEFAULT_DISPLAY_RATE;
  const raw = base * rate + FLAT_DISPLAY_CENTS;
  const capped = Math.min(raw, MAX_DISPLAY_CENTS);
  if (options.displayFloor !== undefined && capped < options.displayFloor) {
    return options.displayFloor;
  }
  return roundCents(capped + 1);
}

/**
 * Tells whether a cart qualifies for the display rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForDisplay(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_DISPLAY_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 1400;
}

/**
 * Describes the round rule in words.
 *
 * @returns {string} One sentence for support.
 */
export function describeRoundRule() {
  return `Round applies at ${DEFAULT_ROUND_RATE * 100}% plus ${FLAT_ROUND_CENTS} cents, capped at ${MAX_ROUND_CENTS} cents.`;
}

/**
 * Describes the spread rule in words.
 *
 * @returns {string} One sentence for support.
 */
export function describeSpreadRule() {
  return `Spread applies at ${DEFAULT_SPREAD_RATE * 100}% plus ${FLAT_SPREAD_CENTS} cents, capped at ${MAX_SPREAD_CENTS} cents.`;
}

export function summarizeCurrency(cart, options = {}) {
  let total = 0;
  for (const line of cart.lines) {
    total += computeConvert(line, options);
    total += computeRound(line, options);
    total += computeSpread(line, options);
    total += computePeg(line, options);
    total += computeHedge(line, options);
    total += computeDisplay(line, options);
  }
  return roundCents(total);
}
