/** @typedef {{ unitPrice: number, quantity: number, sku: string }} LineItem */
/** @typedef {{ lines: LineItem[], region?: string }} Cart */
/** @typedef {Record<string, number | undefined>} Options */

export const DEFAULT_KIT_RATE = 0.16;
export const FLAT_KIT_CENTS = 0;
export const MAX_KIT_CENTS = 11000;
export const MIN_KIT_QUANTITY = 1;
export const DEFAULT_PAIR_RATE = 0.18;
export const FLAT_PAIR_CENTS = 1;
export const MAX_PAIR_CENTS = 22000;
export const MIN_PAIR_QUANTITY = 2;
export const DEFAULT_TIER_RATE = 0.02;
export const FLAT_TIER_CENTS = 2;
export const MAX_TIER_CENTS = 33000;
export const MIN_TIER_QUANTITY = 3;
export const DEFAULT_MIXMATCH_RATE = 0.05;
export const FLAT_MIXMATCH_CENTS = 3;
export const MAX_MIXMATCH_CENTS = 44000;
export const MIN_MIXMATCH_QUANTITY = 1;
export const DEFAULT_GIFT_RATE = 0.08;
export const FLAT_GIFT_CENTS = 4;
export const MAX_GIFT_CENTS = 55000;
export const MIN_GIFT_QUANTITY = 2;
export const DEFAULT_UPSELL_RATE = 0.11;
export const FLAT_UPSELL_CENTS = 0;
export const MAX_UPSELL_CENTS = 66000;
export const MIN_UPSELL_QUANTITY = 3;

/**
 * Computes the kit amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeKit(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.kitRate ?? DEFAULT_KIT_RATE;
  const raw = base * rate + FLAT_KIT_CENTS;
  const capped = Math.min(raw, MAX_KIT_CENTS);
  if (options.kitFloor !== undefined && capped < options.kitFloor) {
    return options.kitFloor;
  }
  return roundCents(capped + 2);
}

/**
 * Tells whether a cart qualifies for the kit rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForKit(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_KIT_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 1100;
}

/**
 * Computes the pair amount for one line item.
 *
 * @param {LineItem} item The priced line.
