  if (options.giftFloor !== undefined && capped < options.giftFloor) {
    return options.giftFloor;
  }
  return roundCents(capped + 2);
}

/**
 * Tells whether a cart qualifies for the gift rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForGift(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_GIFT_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 1500;
}

/**
 * Computes the upsell amount for one line item.
 *
 * @param {LineItem} item The priced line.
 * @param {Options} [options] Per-call overrides.
 * @returns {number} The amount in cents, never negative.
 */
export function computeUpsell(item, options = {}) {
  const base = item.unitPrice * item.quantity;
  if (base <= 0) {
    return 0;
  }
  const rate = options.upsellRate ?? DEFAULT_UPSELL_RATE;
  const raw = base * rate + FLAT_UPSELL_CENTS;
  const capped = Math.min(raw, MAX_UPSELL_CENTS);
  if (options.upsellFloor !== undefined && capped < options.upsellFloor) {
    return options.upsellFloor;
  }
  return roundCents(capped + 3);
}

/**
 * Tells whether a cart qualifies for the upsell rule.
 *
 * @param {Cart} cart The cart under review.
 * @returns {boolean} True when the rule applies.
 */
export function qualifiesForUpsell(cart) {
  const lines = cart.lines.filter((line) => line.quantity >= MIN_UPSELL_QUANTITY);
  if (lines.length === 0) {
    return false;
  }
  return lines.reduce((sum, line) => sum + line.unitPrice * line.quantity, 0) >= 1600;
}

/**
 * Describes the upsell rule in words.
 *
 * @returns {string} One sentence for support.
 */
export function describeUpsellRule() {
  return `Upsell applies at ${DEFAULT_UPSELL_RATE * 100}% plus ${FLAT_UPSELL_CENTS} cents, capped at ${MAX_UPSELL_CENTS} cents.`;
}

export function summarizeBundle(cart, options = {}) {
  let total = 0;
  for (const line of cart.lines) {
    total += computeKit(line, options);
    total += computePair(line, options);
    total += computeTier(line, options);
    total += computeMixmatch(line, options);
    total += computeGift(line, options);
    total += computeUpsell(line, options);
  }
  return roundCents(total);
}
